import { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import API from '../services/api';

export default function WorkerDashboard({ orgId }) {
    const [selectedMonth, setSelectedMonth] = useState(new Date().getMonth() + 1);
    const [selectedYear, setSelectedYear] = useState(new Date().getFullYear());

    // Fetch active pending charges ("in-progress" status for worker view)
    const { data: activePending = [] } = useQuery({
        queryKey: ['activePending', orgId],
        queryFn: async () => {
            const res = await API.get(`/worker/${orgId}/pending`);
            return res.data;
        },
        refetchInterval: 3000
    });

    // Fetch transactions filtered by Month & Year
    const { data: transactions = [] } = useQuery({
        queryKey: ['transactions', orgId, selectedMonth, selectedYear],
        queryFn: async () => {
            const res = await API.get(`/worker/${orgId}/transactions?month=${selectedMonth}&year=${selectedYear}`);
            return res.data;
        }
    });

    return (
        <div className="p-6 max-w-6xl mx-auto space-y-6">
            <h1 className="text-2xl font-bold text-gray-800">Worker & Admin Terminal Control</h1>

            {/* Active In-Progress Charges Section */}
            <div className="bg-white p-5 rounded-xl shadow border border-gray-100">
                <h3 className="font-bold text-lg mb-3 text-gray-700">Awaiting Terminal Taps (In-Progress)</h3>
                {activePending.length === 0 ? (
                    <p className="text-gray-400 text-sm">No charges currently pending a physical card tap.</p>
                ) : (
                    <div className="space-y-2">
                        {activePending.map((item) => (
                            <div key={item.userId} className="flex justify-between items-center bg-amber-50 p-3.5 rounded-lg border border-amber-200">
                                <div>
                                    <p className="font-semibold text-gray-800">Amount: ${item.amount}</p>
                                    <p className="text-xs text-gray-500">Machine ID: {item.machineId}</p>
                                </div>
                                <span className="bg-amber-100 text-amber-800 text-xs px-3 py-1 rounded-full font-bold uppercase tracking-wide animate-pulse">
                                    {item.status}
                                </span>
                            </div>
                        ))}
                    </div>
                )}
            </div>

            {/* Monthly Filter & Transaction Ledger */}
            <div className="bg-white p-5 rounded-xl shadow border border-gray-100">
                <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-6">
                    <h3 className="font-bold text-lg text-gray-700">Company Transaction Ledger</h3>
                    <div className="flex gap-2">
                        <select 
                            value={selectedMonth} 
                            onChange={(e) => setSelectedMonth(e.target.value)}
                            className="border border-gray-300 p-2 rounded-lg text-sm bg-white"
                        >
                            {Array.from({ length: 12 }, (_, i) => (
                                <option key={i + 1} value={i + 1}>
                                    {new Date(0, i).toLocaleString('default', { month: 'long' })}
                                </option>
                            ))}
                        </select>
                        <select 
                            value={selectedYear} 
                            onChange={(e) => setSelectedYear(e.target.value)}
                            className="border border-gray-300 p-2 rounded-lg text-sm bg-white"
                        >
                            <option value="2025">2025</option>
                            <option value="2026">2026</option>
                        </select>
                    </div>
                </div>

                <div className="overflow-x-auto">
                    <table className="w-full text-left border-collapse">
                        <thead>
                            <tr className="border-b text-gray-500 text-xs uppercase tracking-wider">
                                <th className="p-3">Customer</th>
                                <th className="p-3">Type</th>
                                <th className="p-3">Amount</th>
                                <th className="p-3">Machine</th>
                                <th className="p-3">Date</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100">
                            {transactions.length === 0 ? (
                                <tr>
                                    <td colSpan="5" className="p-4 text-center text-gray-400 text-sm">No transactions found for this period.</td>
                                </tr>
                            ) : (
                                transactions.map((tx) => (
                                    <tr key={tx._id} className="text-sm hover:bg-gray-50">
                                        <td className="p-3 font-medium text-gray-800">{tx.userId?.name || 'Unknown'}</td>
                                        <td className="p-3 text-gray-600">{tx.type}</td>
                                        <td className="p-3 font-semibold text-emerald-600">${tx.finalPaid?.toFixed(2)}</td>
                                        <td className="p-3 text-gray-500 font-mono text-xs">{tx.machineId}</td>
                                        <td className="p-3 text-gray-500">{new Date(tx.createdAt).toLocaleDateString()}</td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
}
